@Component("floor-handler")
@ProcessingGroup("floor-processing-group")
public class FloorEventHandler {
	
	// core constructor
	FloorEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateFloorEvent
     */
    @EventHandler
    public void handle( CreateFloorEvent event) {
        entityManager.persist(new Floor(event.getFloorId(), event.getName(), event.getLevel(), event.getBuilding(), event.getRooms()));
    }

    /*
     * @param	event UpdateFloorEvent
     */
    @EventHandler
    public Floor handle( UpdateFloorEvent event) {
    	entityManager.merge(new Floor(event.getFloorId(), event.getName(), event.getLevel(), event.getBuilding(), event.getRooms()));
    }
    
    /*
     * @param	event DeleteFloorEvent
     */
    @EventHandler
    public void on( DeleteFloorEvent event) {
    	Floor entity = new Floor();
   
    	// ------------------------------------------
    	// apply the FloorId
    	// ------------------------------------------
    	entity.setFloorId( event.getFloorId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final FloorRepository floorEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(FloorEventHandler.class.getName());

}
